18	package org.keycloak.common.util;
19	
20	import java.io.File;
21	import java.io.FileInputStream;
22	import java.io.InputStream;
23	import java.security.KeyPair;
24	import java.security.KeyStore;
25	import java.security.PrivateKey;
26	import java.security.PublicKey;
27	import java.util.Arrays;
28	import java.util.List;
29	import java.util.Optional;
30	
31	import org.keycloak.common.constants.GenericConstants;
32	import org.keycloak.common.crypto.CryptoIntegration;
33	
34	/**
35	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
36	 * @version $Revision: 1 $
37	 */
38	public class KeystoreUtil {
39	
40	    public interface StoreFormat {
41	        List<String> getFileExtensions();
42	        String getPrimaryExtension();
43	    };
44	
45	    public enum TruststoreFormat implements StoreFormat {
46	        JKS("jks", "truststore"),
47	        PKCS12("p12", "pfx", "pkcs12"),
48	        PEM("pem", "ca", "crt"),
49	        BCFKS("bcfks");
50	
51	        // Typical file extension for this keystore format
52	        private final List<String> fileExtensions;
53	
54	        TruststoreFormat(String... extensions) {
55	            this.fileExtensions = Arrays.asList(extensions);
56	        }
57	
58	        @Override
59	        public List<String> getFileExtensions() {
60	            return fileExtensions;
61	        }
62	
63	        @Override
64	        public String getPrimaryExtension() {
65	            return fileExtensions.get(0);
66	        }
67	
68	        public boolean isJavaTrustStore() {
69	            return this != PEM;
70	        }
71	    }
72	
73	    public enum KeystoreFormat implements StoreFormat {
74	        JKS("jks"),
75	        PKCS12("p12", "pfx", "pkcs12"),
76	        BCFKS("bcfks");
77	
78	        // Typical file extension for this keystore format
79	        private final List<String> fileExtensions;
80	        KeystoreFormat(String... extensions) {
81	            this.fileExtensions = Arrays.asList(extensions);
82	        }
83	
84	        @Override
85	        public List<String> getFileExtensions() {
86	            return fileExtensions;
87	        }
88	
89	        @Override
90	        public String getPrimaryExtension() {
91	            return fileExtensions.get(0);
92	        }
93	    }
94	
95	    public static KeyStore loadKeyStore(String filename, String password) throws Exception {
96	        return loadKeyStore(filename, password, null);
97	    }
98	
99	    public static KeyStore loadKeyStore(String filename, String password, String preferedType) throws Exception {
100	        String keystoreType = getKeystoreType(preferedType, filename, KeyStore.getDefaultType());
101	        KeyStore trustStore = KeyStore.getInstance(keystoreType);
102	        InputStream trustStream = null;
103	        if (filename.startsWith(GenericConstants.PROTOCOL_CLASSPATH)) {
104	            String resourcePath = filename.replace(GenericConstants.PROTOCOL_CLASSPATH, "");
105	            if (Thread.currentThread().getContextClassLoader() != null) {
106	                trustStream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resourcePath);
107	            }
108	            if (trustStream == null) {
109	                trustStream = KeystoreUtil.class.getResourceAsStream(resourcePath);
110	            }
111	            if (trustStream == null) {
112	                throw new RuntimeException("Unable to find key store in classpath");
113	            }
114	        } else {
115	            trustStream = new FileInputStream(new File(filename));
116	        }
117	        try (InputStream is = trustStream) {
118	            trustStore.load(is, password == null ? null : password.toCharArray());
119	        }
120	        return trustStore;
121	    }
122	
123	    public static KeyPair loadKeyPairFromKeystore(String keystoreFile, String storePassword, String keyPassword, String keyAlias, KeystoreFormat format) {
124	        try (InputStream stream = FindFile.findFile(keystoreFile)) {
125	            KeyStore keyStore = CryptoIntegration.getProvider().getKeyStore(format);
126	
127	            keyStore.load(stream, storePassword.toCharArray());
128	            PrivateKey privateKey = (PrivateKey) keyStore.getKey(keyAlias, keyPassword.toCharArray());
129	            if (privateKey == null) {
130	                throw new RuntimeException("Couldn't load key with alias '" + keyAlias + "' from keystore");
131	            }
132	            PublicKey publicKey = keyStore.getCertificate(keyAlias).getPublicKey();
133	            if (publicKey == null) {
134	                throw new RuntimeException("Couldn't load public key with alias '" + keyAlias + "' from keystore");
135	            }
136	            return new KeyPair(publicKey, privateKey);
137	        } catch (Exception e) {
138	            throw new RuntimeException("Failed to load private key: " + e.getMessage(), e);
139	        }
140	    }
141	
142	    private static <T extends StoreFormat> Optional<T> getStoreFormat(String path, T[] values) {
143	        int lastDotIndex = path.lastIndexOf('.');
144	        if (lastDotIndex > -1) {
145	            String ext = path.substring(lastDotIndex + 1).toLowerCase();
146	            return Arrays.stream(values)
147	                    .filter(ksFormat -> ksFormat.getFileExtensions().contains(ext))
148	                    .findFirst();
149	        }
150	        return Optional.empty();
151	    }
152	
153	    public static Optional<TruststoreFormat> getTruststoreFormat(String path) {
154	        return getStoreFormat(path, TruststoreFormat.values());
155	    }
156	
157	    public static Optional<KeystoreFormat> getKeystoreFormat(String path) {
158	        return getStoreFormat(path, KeystoreFormat.values());
159	    }
160	
161	    private static <T extends StoreFormat> String getStoreType(String preferredType, String path, String defaultType, T[] values) {
162	        // Configured type has precedence
163	        if (preferredType != null) {
164	            return preferredType;
165	        }
166	
167	        // Fallback to path
168	        Optional<StoreFormat> format = getStoreFormat(path, values);
169	        if (format.isPresent()) {
170	            return format.get().toString();
171	        }
172	
173	        // Fallback to default
174	        return defaultType;
175	    }
176	
177	    public static String getTruststoreType(String preferredType, String path, String defaultType) {
178	        return getStoreType(preferredType, path, defaultType, TruststoreFormat.values());
179	    }
180	
181	    /**
182	     * Try to return supported keystore type
183	     *
184	     * @param preferredType The preferred format - usually the one from the configuration. When present, it should be preferred over anything else
185	     * @param path Path of the file. We can try to detect keystore type from that (EG. my-keystore.pkcs12 will return "pkcs12") in case that preferredType is not defined
186	     * @param defaultType Default format as last fallback when none of the above can be used. Should be non-null
187	     * @return format as specified above
188	     */
189	    public static String getKeystoreType(String preferredType, String path, String defaultType) {
190	        return getStoreType(preferredType, path, defaultType, KeystoreFormat.values());
191	    }
192	}
