36	/**
37	 * Extract PrivateKey, PublicKey, and X509Certificate from a DER encoded byte array or file.  Usually
38	 * generated from openssl
39	 *
40	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
41	 * @version $Revision: 1 $
42	 */
43	public final class DerUtils {
44	
45	    private DerUtils() {
46	    }
47	
48	    public static PrivateKey decodePrivateKey(InputStream is)
49	            throws Exception {
50	
51	        DataInputStream dis = new DataInputStream(is);
52	        byte[] keyBytes = new byte[dis.available()];
53	        dis.readFully(keyBytes);
54	        dis.close();
55	
56	        return decodePrivateKey(keyBytes);
57	    }
58	
59	    public static PublicKey decodePublicKey(String encoded) throws NoSuchAlgorithmException, InvalidKeySpecException, NoSuchProviderException {
60	        return decodePublicKey(encoded, "RSA");
61	    }
62	
63	    public static PublicKey decodePublicKey(String encoded, String type) throws NoSuchAlgorithmException, InvalidKeySpecException, NoSuchProviderException {
64	        byte[] der = Base64.getDecoder().decode(encoded);
65	        return decodePublicKey(der, type);
66	    }
67	
68	    public static PublicKey decodePublicKey(byte[] der) throws NoSuchAlgorithmException, InvalidKeySpecException, NoSuchProviderException {
69	        return decodePublicKey(der, "RSA");
70	    }
71	
72	    public static PublicKey decodePublicKey(byte[] der, String type) throws NoSuchAlgorithmException, InvalidKeySpecException, NoSuchProviderException {
73	        X509EncodedKeySpec spec =
74	                new X509EncodedKeySpec(der);
75	        KeyFactory kf = CryptoIntegration.getProvider().getKeyFactory(type);
76	        return kf.generatePublic(spec);
77	    }
78	
79	    public static X509Certificate decodeCertificate(InputStream is) throws Exception {
80	        CertificateFactory cf = CryptoIntegration.getProvider().getX509CertFactory();
81	        X509Certificate cert = (X509Certificate) cf.generateCertificate(is);
82	        is.close();
83	        return cert;
84	    }
85	
86	    public static PrivateKey decodePrivateKey(byte[] der) throws NoSuchAlgorithmException, InvalidKeySpecException, NoSuchProviderException {
87	        PKCS8EncodedKeySpec spec =
88	                new PKCS8EncodedKeySpec(der);
89	        String[] algorithms = { "RSA", "EC" };
90	        for (String algorithm : algorithms) {
91	            try {
92	                return CryptoIntegration.getProvider().getKeyFactory(algorithm).generatePrivate(spec);
93	            } catch (InvalidKeySpecException e) {
94	                // Ignore and try the next algorithm.
95	            }
96	        }
97	        throw new InvalidKeySpecException("Unable to decode the private key with supported algorithms: " + String.join(", ", algorithms));
98	   }
99	}
