242	     * Heuristic check if string might be an IPv6 address.
243	     *
244	     * @param input Any string or null
245	     * @return true, if input string contains only hex digits and at least two colons, before '.' or '%' character.
246	     */
247	    private static boolean mayBeIPv6Address(String input) {
248	        if (input == null) {
249	            return false;
250	        }
251	
252	        boolean result = false;
253	        int colonsCounter = 0;
254	        int length = input.length();
255	        for (int i = 0; i < length; i++) {
256	            char c = input.charAt(i);
257	            if (c == '.' || c == '%') {
258	                // IPv4 in IPv6 or Zone ID detected, end of checking.
259	                break;
260	            }
261	            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')
262	                    || (c >= 'A' && c <= 'F') || c == ':')) {
263	                return false;
264	            } else if (c == ':') {
265	                colonsCounter++;
266	            }
267	        }
268	        if (colonsCounter >= 2) {
269	            result = true;
270	        }
271	        return result;
272	    }
